package com.acme.ems.service;
import com.acme.ems.exception.ApiException;import com.acme.ems.model.*;import com.acme.ems.repository.LeaveBalanceRepository;import com.acme.ems.repository.EmployeeRepository;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)
class LeaveBalanceServiceTest{
 @Mock LeaveBalanceRepository repo;@Mock EmployeeRepository employees;@Mock AuditService audit;LeaveBalanceService service;Employee employee,admin;Map<LeaveType,LeaveBalance> store;
 @BeforeEach void setup(){store=new EnumMap<>(LeaveType.class);service=new LeaveBalanceService(repo,audit,Clock.fixed(Instant.parse("2026-10-13T12:00:00Z"),ZoneOffset.UTC),employees);employee=user(2L,"John");admin=user(1L,"Admin");lenient().when(employees.findByIdForUpdate(2L)).thenReturn(Optional.of(employee));lenient().when(repo.findByEmployeeIdAndYearOrderByLeaveType(eq(2L),anyInt())).thenAnswer(i->List.copyOf(store.values()));lenient().when(repo.findByEmployeeIdAndLeaveTypeAndYear(eq(2L),any(),anyInt())).thenAnswer(i->Optional.ofNullable(store.get(i.getArgument(1))));lenient().when(repo.findForUpdate(eq(2L),any(),anyInt())).thenAnswer(i->Optional.ofNullable(store.get(i.getArgument(1))));lenient().when(repo.save(any())).thenAnswer(i->{LeaveBalance b=i.getArgument(0);if(b.getId()==null)b.setId((long)store.size()+1);store.put(b.getLeaveType(),b);return b;});}
 @Test void initializesExpectedBalances(){service.initialize(employee);assertEquals(15,store.get(LeaveType.VACATION).getTotalAllocated());assertEquals(10,store.get(LeaveType.SICK).getTotalAllocated());assertEquals(5,store.get(LeaveType.PERSONAL).getTotalAllocated());}
 @Test void approvalDeductsAndCannotGoNegative(){service.initialize(employee);service.deduct(employee,LeaveType.VACATION,4,2026,admin,10L);assertEquals(4,store.get(LeaveType.VACATION).getUsed());assertEquals(11,store.get(LeaveType.VACATION).remaining());assertThrows(ApiException.class,()->service.deduct(employee,LeaveType.VACATION,12,2026,admin,11L));}
 @Test void manualAdjustmentRequiresAllocationAtLeastUsedAndIsAudited(){service.initialize(employee);store.get(LeaveType.SICK).setUsed(3);assertThrows(ApiException.class,()->service.adjust(employee,LeaveType.SICK,2,"Correction",admin));service.adjust(employee,LeaveType.SICK,12,"Additional leave",admin);verify(audit).record(eq(admin),eq(AuditAction.LEAVE_BALANCE_UPDATED),eq("LeaveBalance"),anyLong(),contains("Additional leave"));}
 @Test void manualAdjustmentRejectsUnreasonableAnnualAllocation(){service.initialize(employee);var ex=assertThrows(ApiException.class,()->service.adjust(employee,LeaveType.VACATION,Integer.MAX_VALUE,"Overflow",admin));assertEquals("INVALID_LEAVE_ALLOCATION",ex.code());}
 private Employee user(Long id,String name){Employee e=new Employee();e.setId(id);e.setFirstName(name);e.setLastName("User");e.setEmail(name.toLowerCase()+"@x.com");e.setEmployeeId("E"+id);e.setRole(Role.EMPLOYEE);e.setJobTitle("Engineer");e.setDepartment("Tech");e.setDateOfJoining(LocalDate.now());return e;}
}
